class TodoItem {
    final String title;
    final boolean done;

    TodoItem(String title, boolean done) {
        this.title = title;
        this.done = done;
    }
}

class TodoViewModel {
    private final java.util.List<TodoItem> tasks = new java.util.ArrayList<>();

    void addTask(String title) {
        if (title == null || title.isBlank()) throw new IllegalArgumentException("Title required");
        tasks.add(new TodoItem(title, false));
    }
}

