public class Main {
    public static void main(String[] args) {
        Student student = new Student("Ali", 92);
        GradeService service = new GradeService();
        System.out.println(student.getName() + ": " + service.gradeFor(student));
    }
}

public class Student {
    private final String name;
    private final int marks;

    public Student(String name, int marks) {
        if (name == null || name.isBlank()) throw new IllegalArgumentException("Name is required");
        if (marks < 0 || marks > 100) throw new IllegalArgumentException("Marks must be 0 to 100");
        this.name = name;
        this.marks = marks;
    }

    public String getName() { return name; }
    public int getMarks() { return marks; }
}

public class GradeService {
    public String gradeFor(Student student) {
        int marks = student.getMarks();
        if (marks >= 90) return "A";
        if (marks >= 80) return "B";
        if (marks >= 70) return "C";
        if (marks >= 60) return "D";
        return "F";
    }
}

public class Main {
    public static void main(String[] args) {
        BankAccount account = new BankAccount("Ali", 100);
        account.deposit(25);
        account.withdraw(55);
        System.out.println(account.getBalance());
    }
}

public class BankAccount {
    private final String owner;
    private int balance;

    public BankAccount(String owner, int openingBalance) {
        if (owner == null || owner.isBlank()) throw new IllegalArgumentException("Owner is required");
        if (openingBalance < 0) throw new IllegalArgumentException("Opening balance cannot be negative");
        this.owner = owner;
        this.balance = openingBalance;
    }

    public void deposit(int amount) {
        if (amount <= 0) throw new IllegalArgumentException("Deposit must be positive");
        balance += amount;
    }

    public void withdraw(int amount) {
        if (amount <= 0) throw new IllegalArgumentException("Withdrawal must be positive");
        if (amount > balance) throw new IllegalArgumentException("Insufficient balance");
        balance -= amount;
    }

    public int getBalance() { return balance; }
    public String getOwner() { return owner; }
}

public class Main {
