public class Task {
    private final String title;
    private boolean done;

    public Task(String title) {
        if (title == null || title.isBlank()) throw new IllegalArgumentException("Title required");
        this.title = title;
    }

    public boolean isDone() { return done; }
    public String getTitle() { return title; }
}

import java.util.ArrayList;
import java.util.List;

public class FakeTaskDao {
    private final List<Task> tasks = new ArrayList<>();

    public void insert(Task task) { tasks.add(task); }
    public List<Task> all() { return tasks; }
}

public class TaskRepository {
    private final FakeTaskDao dao;

    public TaskRepository(FakeTaskDao dao) {
        this.dao = dao;
    }

    public void add(String title) { dao.insert(new Task(title)); }
    public long openCount() { return dao.all().stream().filter(task -> !task.isDone()).count(); }
}

