public class Main {
    public static void main(String[] args) {
        HttpServerCore server = new HttpServerCore();
        System.out.println(server.handle("GET / HTTP/1.1").split("\\r?\\n")[0]);
    }
}

public class HttpServerCore {
    public String handle(String requestLine) {
        if (requestLine == null || !requestLine.startsWith("GET ")) {
            return "HTTP/1.1 400 Bad Request\r\n\r\nBad request";
        }
        return "HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\n\r\nHello from Java";
    }
}

public class Main {
    public static void main(String[] args) {
        MiniJsonParser parser = new MiniJsonParser();
        System.out.println(parser.valueOf("{\"name\":\"Ali\",\"level\":\"Java\"}", "name"));
    }
}

public class MiniJsonParser {
    public String valueOf(String json, String key) {
        String normalized = json.replace("{", "").replace("}", "").replace("\"", "");
        for (String part : normalized.split(",")) {
            String[] pair = part.split(":", 2);
            if (pair.length == 2 && pair[0].trim().equals(key)) {
                return pair[1].trim();
            }
        }
        return "";
    }
}

public class Main {
    public static void main(String[] args) {
        ObjectStore store = new ObjectStore();
        String key = store.save("hello");
        System.out.println(store.read(key));
    }
}

import java.util.HashMap;
import java.util.Map;

public class ObjectStore {
    private final Map<String, String> objects = new HashMap<>();

    public String save(String content) {
        String key = Integer.toHexString(content.hashCode());
        objects.put(key, content);
        return key;
    }

    public String read(String key) {
        return objects.getOrDefault(key, "missing");
    }
}

