public class Main {
    public static void main(String[] args) {
        KeyValueStore store = new KeyValueStore();
        store.set("foo", "bar");
        System.out.println(store.get("foo"));
    }
}

import java.util.HashMap;
import java.util.Map;

public class KeyValueStore {
    private final Map<String, String> values = new HashMap<>();

    public void set(String key, String value) {
        if (key == null || key.isBlank()) throw new IllegalArgumentException("Key required");
        values.put(key, value);
    }

    public String get(String key) {
        return values.getOrDefault(key, "nil");
    }
}

public class Main {
    public static void main(String[] args) {
        SecurityService security = new SecurityService();
        User user = new User("Ali", "USER");
        System.out.println(security.protectedPage(user));
    }
}

public class User {
    private final String name;
    private final String role;

    public User(String name, String role) {
        this.name = name;
        this.role = role;
    }

    public String getName() { return name; }
    public String getRole() { return role; }
}

public class SecurityService {
    public String protectedPage(User user) {
        if (user == null) return "Please sign in";
        if (!"USER".equals(user.getRole()) && !"ADMIN".equals(user.getRole())) return "Forbidden";
        return "Welcome " + user.getName();
    }
}
